	h := hmac.New(sha256.New, []byte(secret))
	h.Write(payload)
	expectedHex := hex.EncodeToString(h.Sum(nil))

	// Assume the signature header is called "X-Signature"
	sigHeader := ""
	if h, ok := http.Header(rw).Get("X-Signature"); ok {
		sigHeader = h
	}
	return hmac.Equal([]byte(expectedHex), []byte(sigHeader))
}

func main() {
	secret := "my‑super‑secret"
	payload := []byte("Hello, world!")

	// Simulate header extraction:
	httpReq := &http.Request{
		Header: http.Header{"X-Signature": {hmac.New(sha256.New, []byte(secret)).Sum(nil).Hex()}},
	}
	fmt.Println(verifyHMACSha256(payload, secret))
}
